CREATE TABLE countries (id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE currencies (id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, code text UNIQUE NOT NULL);
CREATE TABLE fuel_types (id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, unit text NOT NULL CHECK(unit IN ('l','kg')));
INSERT INTO fuel_types(code,name,unit) VALUES ('EURO95','Benzine · E10','l'),('DIESEL','Diesel · B7','l'),('EURO98','Euro 98 · E5','l'),('DIESEL_SPECIAL','Premium diesel','l'),('AUTOGAS','LPG','l'),('CNG','CNG','kg');
CREATE TABLE query_plans (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), verified_at timestamptz, active boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX one_active_plan ON query_plans(active) WHERE active;
CREATE TABLE query_shards (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, plan_id integer NOT NULL REFERENCES query_plans(id), bounds double precision[] NOT NULL CHECK(array_length(bounds,1)=4), enabled boolean NOT NULL DEFAULT true);
CREATE TABLE collection_runs (hour_id integer PRIMARY KEY, plan_id integer NOT NULL REFERENCES query_plans(id), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, status smallint NOT NULL DEFAULT 0 CHECK(status BETWEEN 0 AND 3), stations integer NOT NULL DEFAULT 0, changes integer NOT NULL DEFAULT 0);
CREATE TABLE collection_shards (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, hour_id integer NOT NULL REFERENCES collection_runs(hour_id), shard_id integer NOT NULL REFERENCES query_shards(id), attempt smallint NOT NULL, started_at timestamptz NOT NULL, fetched_at timestamptz NOT NULL, status smallint NOT NULL CHECK(status IN (1,2)), station_count integer NOT NULL DEFAULT 0, error text, UNIQUE(hour_id,shard_id,attempt));
CREATE TABLE stations (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, source_id text NOT NULL UNIQUE, country_id smallint NOT NULL REFERENCES countries(id), latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), title text NOT NULL, address jsonb NOT NULL, opening_hours jsonb NOT NULL, facilities jsonb, details_checked_at timestamptz);
CREATE INDEX stations_coordinates ON stations(latitude,longitude);
CREATE TABLE station_state (station_id integer PRIMARY KEY REFERENCES stations(id), last_seen_batch_id integer NOT NULL REFERENCES collection_shards(id), present boolean NOT NULL) WITH (fillfactor=75);
CREATE TABLE station_presence_changes (station_id integer NOT NULL REFERENCES stations(id), observed_hour integer NOT NULL REFERENCES collection_runs(hour_id), present boolean NOT NULL, PRIMARY KEY(station_id,observed_hour));
CREATE TABLE station_fuels (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, station_id integer NOT NULL REFERENCES stations(id), fuel_type_id smallint NOT NULL REFERENCES fuel_types(id), UNIQUE(station_id,fuel_type_id));
CREATE TABLE current_prices (series_id integer PRIMARY KEY REFERENCES station_fuels(id), observed_hour integer NOT NULL, price_milli integer, currency_id smallint NOT NULL REFERENCES currencies(id), state smallint NOT NULL CHECK(state BETWEEN 0 AND 2), tier smallint NOT NULL DEFAULT 0, CHECK((state=0 AND price_milli IS NOT NULL AND price_milli>0) OR (state IN (1,2) AND price_milli IS NULL))) WITH (fillfactor=85);
CREATE TABLE price_changes (series_id integer NOT NULL REFERENCES station_fuels(id), observed_hour integer NOT NULL REFERENCES collection_runs(hour_id), price_milli integer, currency_id smallint NOT NULL REFERENCES currencies(id), state smallint NOT NULL CHECK(state BETWEEN 0 AND 2), PRIMARY KEY(series_id,observed_hour), CHECK((state=0 AND price_milli IS NOT NULL AND price_milli>0) OR (state IN (1,2) AND price_milli IS NULL))) PARTITION BY RANGE(observed_hour);
CREATE TABLE geocode_cache (key text PRIMARY KEY, results jsonb NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE service_limits (name text PRIMARY KEY, next_at timestamptz NOT NULL);
